// Perfiles de los 4 familiares monitoreados
const PROFILES = {
    'XIAOMI-PAPA-001': {
        deviceId: 'XIAOMI-PAPA-001',
        memberId: 'familia-garcia-papa',
        memberName: 'Roberto García',
        relationship: 'padre',
        heartRate: { min: 65, max: 85, baseline: 72 },
        oxygenLevel: { min: 95, max: 99, baseline: 96.5 },
        bodyTemperature: { min: 36.2, max: 37.0, baseline: 36.5 },
        stepsPerInterval: { min: 5, max: 25 }
    },
    'APPLE-MAMA-002': {
        deviceId: 'APPLE-MAMA-002',
        memberId: 'familia-garcia-mama',
        memberName: 'Elena García',
        relationship: 'madre',
        heartRate: { min: 60, max: 80, baseline: 68 },
        oxygenLevel: { min: 96, max: 99, baseline: 98 },
        bodyTemperature: { min: 36.4, max: 37.2, baseline: 36.8 },
        stepsPerInterval: { min: 8, max: 30 }
    },
    'FITBIT-ABUELO-003': {
        deviceId: 'FITBIT-ABUELO-003',
        memberId: 'familia-garcia-abuelo',
        memberName: 'José García Sr.',
        relationship: 'abuelo',
        heartRate: { min: 55, max: 75, baseline: 58 },
        oxygenLevel: { min: 92, max: 97, baseline: 94 },
        bodyTemperature: { min: 36.0, max: 36.8, baseline: 36.4 },
        stepsPerInterval: { min: 2, max: 10 }
    },
    'SIM-NODERED-004': {
        deviceId: 'SIM-NODERED-004',
        memberId: 'familia-garcia-sim',
        memberName: 'Simulador Pruebas',
        relationship: 'otro',
        heartRate: { min: 60, max: 100, baseline: 75 },
        oxygenLevel: { min: 94, max: 99, baseline: 97 },
        bodyTemperature: { min: 36.0, max: 37.5, baseline: 36.6 },
        stepsPerInterval: { min: 0, max: 50 }
    }
};

// Función para generar número aleatorio con distribución gaussiana
function gaussianRandom(mean, stdDev) {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    while (v === 0) v = Math.random();
    const num = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
    return num * stdDev + mean;
}

// Función para generar entero aleatorio en rango
function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Verificar modo anomalía
const anomalyMode = global.get('anomalyMode') || false;

// Generar datos para cada dispositivo
const messages = [];
const deviceIds = Object.keys(PROFILES);

for (const deviceId of deviceIds) {
    const profile = PROFILES[deviceId];
    const now = new Date();

    // Generar valores base con variación natural
    let heartRate = gaussianRandom(
        profile.heartRate.baseline,
        (profile.heartRate.max - profile.heartRate.min) / 6
    );

    let oxygenLevel = gaussianRandom(
        profile.oxygenLevel.baseline,
        (profile.oxygenLevel.max - profile.oxygenLevel.min) / 6
    );

    let bodyTemperature = gaussianRandom(
        profile.bodyTemperature.baseline,
        (profile.bodyTemperature.max - profile.bodyTemperature.min) / 6
    );

    // Inyectar anomalía si está activo (30% de probabilidad)
    let isAnomaly = false;
    if (anomalyMode && Math.random() < 0.3) {
        isAnomaly = true;
        const anomalyTypes = ['hr_high', 'hr_low', 'spo2_low', 'temp_high', 'temp_low'];
        const anomalyType = anomalyTypes[randomInt(0, anomalyTypes.length - 1)];

        switch (anomalyType) {
            case 'hr_high':
                heartRate = randomInt(125, 140);
                break;
            case 'hr_low':
                heartRate = randomInt(40, 48);
                break;
            case 'spo2_low':
                oxygenLevel = randomInt(82, 88);
                break;
            case 'temp_high':
                bodyTemperature = 38.5 + Math.random() * 1.5;
                break;
            case 'temp_low':
                bodyTemperature = 33.5 + Math.random() * 1;
                break;
        }
    }

    // Obtener y actualizar pasos acumulados
    const stepsKey = 'steps_' + deviceId;
    let currentSteps = global.get(stepsKey) || 0;
    const stepsIncrement = randomInt(
        profile.stepsPerInterval.min,
        profile.stepsPerInterval.max
    );
    currentSteps += stepsIncrement;
    global.set(stepsKey, currentSteps);

    // Construir payload según especificación del proyecto
    const payload = {
        deviceId: profile.deviceId,
        memberId: profile.memberId,
        memberName: profile.memberName,
        relationship: profile.relationship,
        heartRate: Math.round(heartRate),
        oxygenLevel: parseFloat(Math.min(100, Math.max(50, oxygenLevel)).toFixed(1)),
        bodyTemperature: parseFloat(Math.min(42, Math.max(32, bodyTemperature)).toFixed(2)),
        steps: currentSteps,
        timestamp: now.toISOString(),
        isAnomaly: isAnomaly
    };

    messages.push({
        payload: payload,
        topic: 'vitals/' + deviceId,
        deviceId: deviceId
    });
}

// Retornar array de mensajes (uno por cada dispositivo)
return [messages];

const statusCode = msg.statusCode || 0;
const now = new Date().toLocaleTimeString('es-MX');
let statusMsg = '';
let statusColor = 'green';

if (statusCode === 200 || statusCode === 201) {
    statusMsg = `✅ OK (${statusCode}) - ${now}`;
    statusColor = 'green';
} else if (statusCode === 400) {
    statusMsg = `⚠️ Bad Request (400) - ${now}`;
    statusColor = 'yellow';
} else if (statusCode === 401) {
    statusMsg = `🔒 Unauthorized (401) - ${now}`;
    statusColor = 'red';
} else if (statusCode === 500) {
    statusMsg = `❌ Server Error (500) - ${now}`;
    statusColor = 'red';
} else if (statusCode === 0) {
    statusMsg = `⏱️ Timeout/No Response - ${now}`;
    statusColor = 'grey';
} else {
    statusMsg = `❓ Unknown (${statusCode}) - ${now}`;
    statusColor = 'grey';
}

node.status({fill: statusColor, shape: 'dot', text: statusMsg});

msg.payload = statusMsg;
msg.statusCode = statusCode;
return msg;

const selectedDevice = global.get('selectedDevice') || 'ALL';
const deviceId = msg.payload.deviceId;

// Si está seleccionado 'ALL' o coincide con el dispositivo, enviar al dashboard
if (selectedDevice === 'ALL' || selectedDevice === deviceId) {
    // Crear mensajes separados para cada gauge/chart
    const hrMsg = { payload: msg.payload.heartRate, topic: 'heartRate', deviceId: deviceId, memberName: msg.payload.memberName };
    const spo2Msg = { payload: msg.payload.oxygenLevel, topic: 'oxygenLevel', deviceId: deviceId, memberName: msg.payload.memberName };
    const tempMsg = { payload: msg.payload.bodyTemperature, topic: 'temperature', deviceId: deviceId, memberName: msg.payload.memberName };
    const stepsMsg = { payload: msg.payload.steps, topic: 'steps', deviceId: deviceId, memberName: msg.payload.memberName };
    const rawMsg = { payload: msg.payload, topic: 'raw' };

    return [hrMsg, spo2Msg, tempMsg, stepsMsg, rawMsg];
}

return [null, null, null, null, null];

const data = msg.payload;
const alerts = [];

// Umbrales según VitalSync Product Design
const THRESHOLDS = {
    heartRate: {
        critical_low: 50,
        warning_low: 60,
        warning_high: 100,
        critical_high: 120
    },
    oxygenLevel: {
        critical: 90,
        warning: 95
    },
    bodyTemperature: {
        critical_low: 35.0,
        warning_low: 36.1,
        warning_high: 37.2,
        critical_high: 38.0
    },
    steps: {
        critical: 2000,
        warning: 5000
    }
};

// Verificar Heart Rate
if (data.heartRate < THRESHOLDS.heartRate.critical_low) {
    alerts.push({
        level: 'CRITICAL',
        icon: '🔴',
        metric: 'Heart Rate',
        message: `${data.memberName}: HR ${data.heartRate} bpm (crítico bajo <${THRESHOLDS.heartRate.critical_low})`
    });
} else if (data.heartRate > THRESHOLDS.heartRate.critical_high) {
    alerts.push({
        level: 'CRITICAL',
        icon: '🔴',
        metric: 'Heart Rate',
        message: `${data.memberName}: HR ${data.heartRate} bpm (crítico alto >${THRESHOLDS.heartRate.critical_high})`
    });
} else if (data.heartRate < THRESHOLDS.heartRate.warning_low || data.heartRate > THRESHOLDS.heartRate.warning_high) {
    alerts.push({
        level: 'WARNING',
        icon: '⚠️',
        metric: 'Heart Rate',
        message: `${data.memberName}: HR ${data.heartRate} bpm (fuera de rango normal)`
    });
}

// Verificar Oxygen Level
if (data.oxygenLevel < THRESHOLDS.oxygenLevel.critical) {
    alerts.push({
        level: 'CRITICAL',
        icon: '🔴',
        metric: 'Oxygen Level',
        message: `${data.memberName}: SpO2 ${data.oxygenLevel}% (crítico <${THRESHOLDS.oxygenLevel.critical}%)`
    });
} else if (data.oxygenLevel < THRESHOLDS.oxygenLevel.warning) {
    alerts.push({
        level: 'WARNING',
        icon: '⚠️',
        metric: 'Oxygen Level',
        message: `${data.memberName}: SpO2 ${data.oxygenLevel}% (bajo)`
    });
}

// Verificar Temperature
if (data.bodyTemperature < THRESHOLDS.bodyTemperature.critical_low) {
    alerts.push({
        level: 'CRITICAL',
        icon: '🔴',
        metric: 'Temperature',
        message: `${data.memberName}: Temp ${data.bodyTemperature}°C (hipotermia)`
    });
} else if (data.bodyTemperature > THRESHOLDS.bodyTemperature.critical_high) {
    alerts.push({
        level: 'CRITICAL',
        icon: '🔴',
        metric: 'Temperature',
        message: `${data.memberName}: Temp ${data.bodyTemperature}°C (fiebre alta)`
    });
} else if (data.bodyTemperature < THRESHOLDS.bodyTemperature.warning_low || data.bodyTemperature > THRESHOLDS.bodyTemperature.warning_high) {
    alerts.push({
        level: 'WARNING',
        icon: '⚠️',
        metric: 'Temperature',
        message: `${data.memberName}: Temp ${data.bodyTemperature}°C (fuera de rango)`
    });
}

// Si hay alertas, enviarlas
if (alerts.length > 0) {
    return { payload: alerts, topic: 'alerts' };
}

return null;

// Reiniciar contadores de pasos
global.set('steps_XIAOMI-PAPA-001', 0);
global.set('steps_APPLE-MAMA-002', 0);
global.set('steps_FITBIT-ABUELO-003', 0);
global.set('steps_SIM-NODERED-004', 0);

node.status({fill:'green', shape:'dot', text: 'Pasos reiniciados'});

msg.payload = 'Contadores de pasos reiniciados a 0';
return msg;
